parameters.jsCode:
// ACR TI-RADS Code Tool
// Calculates ACR TI-RADS score and category

const input = $json;

// -----------------------------
// Validate required inputs
// -----------------------------

const requiredFields = [
  "composition",
  "echogenicity",
  "shape",
  "margin",
  "echogenic_foci"
];

const missingFields = requiredFields.filter(
  field =>
    input[field] === undefined ||
    input[field] === null
);

if (missingFields.length > 0) {
  return `Missing required value(s): ${missingFields.join(", ")}`;
}

// -----------------------------
// Normalize echogenic foci
// -----------------------------

const echogenicFoci = Array.isArray(input.echogenic_foci)
  ? input.echogenic_foci
  : [input.echogenic_foci];

// -----------------------------
// Special cases
// -----------------------------

if (
  input.composition === "cystic" ||
  input.composition === "spongiform"
) {
  return JSON.stringify({
    status: "calculated",
    calculator: "ACR TI-RADS",

    findings: {
      composition: input.composition,
      echogenicity: input.echogenicity,
      shape: input.shape,
      margin: input.margin,
      echogenic_foci: echogenicFoci,
      size_mm: input.size_mm ?? null
    },

    result: {
      total_score: 0,
      category: "TR1",
      interpretation: "Benign"
    },

    component_scores: {
      composition: 0,
      echogenicity: 0,
      shape: 0,
      margin: 0,
      echogenic_foci: 0
    },

    echogenic_foci_details: [],

    note:
      "Cystic/almost completely cystic or spongiform nodule: remaining categories are not scored."
  });
}

// -----------------------------
// Composition
// -----------------------------

const compositionScores = {
  mixed_cystic_solid: 1,
  solid: 2,
  indeterminate: 2
};

if (!(input.composition in compositionScores)) {
  return `Invalid composition value: ${input.composition}`;
}

const compositionScore =
  compositionScores[input.composition];

// -----------------------------
// Echogenicity
// -----------------------------

const echogenicityScores = {
  hyperechoic_or_isoechoic: 1,
  hypoechoic: 2,
  very_hypoechoic: 3,
  indeterminate: 1
};

if (input.echogenicity === "anechoic") {
  return "Invalid echogenicity: anechoic should not be used for a non-cystic nodule.";
}

if (!(input.echogenicity in echogenicityScores)) {
  return `Invalid echogenicity value: ${input.echogenicity}`;
}

const echogenicityScore =
  echogenicityScores[input.echogenicity];

// -----------------------------
// Shape
// -----------------------------

const shapeScores = {
  wider_than_tall: 0,
  taller_than_wide: 3
};

if (!(input.shape in shapeScores)) {
  return `Invalid shape value: ${input.shape}`;
}

const shapeScore = shapeScores[input.shape];

// -----------------------------
// Margin
// -----------------------------

const marginScores = {
  smooth: 0,
  ill_defined: 0,
  lobulated_or_irregular: 2,
  extrathyroidal_extension: 3,
  indeterminate: 0
};

if (!(input.margin in marginScores)) {
  return `Invalid margin value: ${input.margin}`;
}

const marginScore = marginScores[input.margin];

// -----------------------------
// Echogenic foci
// -----------------------------

const fociScores = {
  none_or_large_comet_tail: 0,
  macrocalcification: 1,
  peripheral_rim_calcification: 2,
  punctate_echogenic_foci: 3
};

let echogenicFociScore = 0;
const fociDetails = [];

for (const focus of echogenicFoci) {

  if (!(focus in fociScores)) {
    return `Invalid echogenic foci value: ${focus}`;
  }

  const points = fociScores[focus];

  echogenicFociScore += points;

  fociDetails.push({
    type: focus,
    points
  });
}

// -----------------------------
// Total score
// -----------------------------

const totalScore =
  compositionScore +
  echogenicityScore +
  shapeScore +
  marginScore +
  echogenicFociScore;

// -----------------------------
// TI-RADS category
// -----------------------------

let category;
let interpretation;

if (totalScore === 0) {
  category = "TR1";
  interpretation = "Benign";
} else if (totalScore === 2) {
  category = "TR2";
  interpretation = "Not suspicious";
} else if (totalScore === 3) {
  category = "TR3";
  interpretation = "Mildly suspicious";
} else if (totalScore >= 4 && totalScore <= 6) {
  category = "TR4";
  interpretation = "Moderately suspicious";
} else if (totalScore >= 7) {
  category = "TR5";
  interpretation = "Highly suspicious";
} else {
  return `Invalid ACR TI-RADS total score: ${totalScore}`;
}

// -----------------------------
// Final response
// -----------------------------

return JSON.stringify({
  status: "calculated",
  calculator: "ACR TI-RADS",

  findings: {
    composition: input.composition,
    echogenicity: input.echogenicity,
    shape: input.shape,
    margin: input.margin,
    echogenic_foci: echogenicFoci,
    size_mm: input.size_mm ?? null
  },

  result: {
    total_score: totalScore,
    category,
    interpretation
  },

  component_scores: {
    composition: compositionScore,
    echogenicity: echogenicityScore,
    shape: shapeScore,
    margin: marginScore,
    echogenic_foci: echogenicFociScore
  },

  echogenic_foci_details: fociDetails
});

