parameters.jsCode:
const input = $json;

// ==========================================
// BI-RADS Decision Support Tool
// ACR BI-RADS v2025
// ==========================================

const result = {
  tool: "BI-RADS",
  framework: "ACR BI-RADS v2025",

  modality: input.modality || null,
  clinical_context: input.clinical_context || null,

  findings_summary: [],
  key_descriptors: [],
  assessment_basis: [],
  warnings: [],

  assessment_category: null,
  assessment_label: null,
  management_recommendation: null,

  status: "insufficient_data",
  requires_radiologist_review: true,

  note:
    "This tool provides deterministic decision support from structured inputs. Final BI-RADS assessment requires interpretation of the complete breast imaging examination by a qualified radiologist."
};

// ==========================================
// Helpers
// ==========================================

function addWarning(message) {
  if (!result.warnings.includes(message)) {
    result.warnings.push(message);
  }
}

function addBasis(message) {
  if (!result.assessment_basis.includes(message)) {
    result.assessment_basis.push(message);
  }
}

function addDescriptor(message) {
  if (!result.key_descriptors.includes(message)) {
    result.key_descriptors.push(message);
  }
}

// ==========================================
// Basic validation
// ==========================================

if (!input.modality) {
  addWarning("Modality is missing.");
}

if (!Array.isArray(input.findings) || input.findings.length === 0) {
  addWarning("No structured imaging findings were provided.");
}

if (!input.modality || !Array.isArray(input.findings) || input.findings.length === 0) {
  return JSON.stringify(result);
}

// ==========================================
// Findings summary + descriptors
// ==========================================

for (const finding of input.findings) {

  result.findings_summary.push({
    finding_type: finding.finding_type || null,
    location: finding.location || null,
    size_mm: finding.size_mm ?? null,
    change_from_prior: finding.change_from_prior || null
  });

  if (finding.finding_type) {
    addDescriptor(`Finding type: ${finding.finding_type}`);
  }

  if (finding.location) {
    addDescriptor(`Location: ${finding.location}`);
  }

  if (finding.size_mm !== undefined && finding.size_mm !== null) {
    addDescriptor(`Size: ${finding.size_mm} mm`);
  }

  if (finding.change_from_prior) {
    addDescriptor(`Change from prior: ${finding.change_from_prior}`);
  }

  // ----------------------------------------
  // Mammography descriptors
  // ----------------------------------------

  if (input.modality === "mammography" && finding.mammography) {

    const m = finding.mammography;

    if (m.breast_composition) {
      addDescriptor(`Breast composition: ${m.breast_composition}`);
    }

    if (m.mass_shape && m.mass_shape !== "not_applicable") {
      addDescriptor(`Mammographic mass shape: ${m.mass_shape}`);
    }

    if (m.mass_margin && m.mass_margin !== "not_applicable") {
      addDescriptor(`Mammographic mass margin: ${m.mass_margin}`);
    }

    if (m.mass_density && m.mass_density !== "not_applicable") {
      addDescriptor(`Mammographic mass density: ${m.mass_density}`);
    }

    if (
      m.calcification_morphology &&
      m.calcification_morphology !== "not_applicable"
    ) {
      addDescriptor(
        `Calcification morphology: ${m.calcification_morphology}`
      );
    }

    if (
      m.calcification_distribution &&
      m.calcification_distribution !== "not_applicable"
    ) {
      addDescriptor(
        `Calcification distribution: ${m.calcification_distribution}`
      );
    }

    if (
      m.asymmetry_type &&
      m.asymmetry_type !== "not_applicable"
    ) {
      addDescriptor(`Asymmetry type: ${m.asymmetry_type}`);
    }

    if (m.architectural_distortion === true) {
      addDescriptor("Architectural distortion: present");
    }

    if (
      Array.isArray(m.associated_features) &&
      m.associated_features.length > 0
    ) {
      for (const feature of m.associated_features) {
        if (feature !== "none") {
          addDescriptor(`Associated feature: ${feature}`);
        }
      }
    }
  }

  // ----------------------------------------
  // Ultrasound descriptors
  // ----------------------------------------

  if (input.modality === "ultrasound" && finding.ultrasound) {

    const u = finding.ultrasound;

    if (u.composition && u.composition !== "not_applicable") {
      addDescriptor(`US composition: ${u.composition}`);
    }

    if (u.shape && u.shape !== "not_applicable") {
      addDescriptor(`US shape: ${u.shape}`);
    }

    if (u.orientation && u.orientation !== "not_applicable") {
      addDescriptor(`US orientation: ${u.orientation}`);
    }

    if (u.margin && u.margin !== "not_applicable") {
      addDescriptor(`US margin: ${u.margin}`);
    }

    if (u.echo_pattern && u.echo_pattern !== "not_applicable") {
      addDescriptor(`US echo pattern: ${u.echo_pattern}`);
    }

    if (
      u.posterior_features &&
      u.posterior_features !== "not_applicable"
    ) {
      addDescriptor(`Posterior features: ${u.posterior_features}`);
    }

    if (u.vascularity && u.vascularity !== "not_assessed") {
      addDescriptor(`Vascularity: ${u.vascularity}`);
    }

    if (u.cyst_type && u.cyst_type !== "not_applicable") {
      addDescriptor(`Cyst type: ${u.cyst_type}`);
    }

    if (u.elasticity && u.elasticity !== "not_assessed") {
      addDescriptor(`Elasticity: ${u.elasticity}`);
    }
  }

  // ----------------------------------------
  // MRI descriptors
  // ----------------------------------------

  if (input.modality === "mri" && finding.mri) {

    const r = finding.mri;

    if (r.finding_type) {
      addDescriptor(`MRI finding type: ${r.finding_type}`);
    }

    if (r.mass_shape && r.mass_shape !== "not_applicable") {
      addDescriptor(`MRI mass shape: ${r.mass_shape}`);
    }

    if (r.mass_margin && r.mass_margin !== "not_applicable") {
      addDescriptor(`MRI mass margin: ${r.mass_margin}`);
    }

    if (
      r.mass_internal_enhancement &&
      r.mass_internal_enhancement !== "not_applicable"
    ) {
      addDescriptor(
        `MRI internal enhancement: ${r.mass_internal_enhancement}`
      );
    }

    if (
      r.non_mass_distribution &&
      r.non_mass_distribution !== "not_applicable"
    ) {
      addDescriptor(
        `MRI non-mass distribution: ${r.non_mass_distribution}`
      );
    }

    if (
      r.non_mass_internal_enhancement &&
      r.non_mass_internal_enhancement !== "not_applicable"
    ) {
      addDescriptor(
        `MRI non-mass internal enhancement: ${r.non_mass_internal_enhancement}`
      );
    }

    if (
      r.kinetic_pattern &&
      r.kinetic_pattern !== "not_assessed"
    ) {
      addDescriptor(`MRI kinetic pattern: ${r.kinetic_pattern}`);
    }

    if (
      r.background_parenchymal_enhancement &&
      r.background_parenchymal_enhancement !== "not_assessed"
    ) {
      addDescriptor(
        `Background parenchymal enhancement: ${r.background_parenchymal_enhancement}`
      );
    }
  }
}

// ==========================================
// PRIORITY 1
// BI-RADS 0 - Incomplete
// ==========================================

if (input.additional_imaging_needed === true) {

  result.assessment_category = "0";
  result.assessment_label = "Incomplete";

  result.management_recommendation =
    "Additional imaging evaluation and/or prior imaging comparison is required.";

  addBasis(
    "The examination is marked as incomplete and additional imaging or comparison is required."
  );

  result.status = "complete";

  return JSON.stringify(result);
}

// ==========================================
// PRIORITY 2
// BI-RADS 6 - Known biopsy-proven malignancy
// ==========================================

if (
  input.known_biopsy_proven_malignancy === true
) {

  result.assessment_category = "6";
  result.assessment_label =
    "Known Biopsy-Proven Malignancy";

  result.management_recommendation =
    "Appropriate management of the known biopsy-proven malignancy is required.";

  addBasis(
    "A biopsy-proven malignancy corresponding to the imaging finding is documented."
  );

  result.status = "complete";

  return JSON.stringify(result);
}

// ==========================================
// BI-RADS 1 - Negative
// ==========================================

const onlyNoSuspiciousFinding =
  input.findings.length === 1 &&
  input.findings[0].finding_type === "no_suspicious_finding";

if (onlyNoSuspiciousFinding) {

  result.assessment_category = "1";
  result.assessment_label = "Negative";

  result.management_recommendation =
    "Routine screening or management according to the applicable clinical screening protocol.";

  addBasis(
    "No suspicious breast imaging finding was provided."
  );

  result.status = "complete";

  return JSON.stringify(result);
}

// ==========================================
// BI-RADS 2 - Benign
// ==========================================

let benignFinding = false;

for (const finding of input.findings) {

  if (
    input.modality === "ultrasound" &&
    finding.finding_type === "cyst" &&
    finding.ultrasound &&
    finding.ultrasound.cyst_type === "simple"
  ) {
    benignFinding = true;

    addBasis(
      "A simple cyst was explicitly identified in the structured ultrasound findings."
    );
  }
}

if (benignFinding) {

  result.assessment_category = "2";
  result.assessment_label = "Benign Finding(s)";

  result.management_recommendation =
    "Benign finding; routine management is appropriate unless clinical circumstances indicate otherwise.";

  result.status = "complete";

  return JSON.stringify(result);
}

// ==========================================
// BI-RADS 3 - Probably Benign
// ==========================================

let probablyBenign = false;

for (const finding of input.findings) {

  // Stable finding
  if (finding.change_from_prior === "stable") {
    probablyBenign = true;
  }

  // Typical probably-benign US mass pattern
  if (
    input.modality === "ultrasound" &&
    finding.ultrasound
  ) {

    const u = finding.ultrasound;

    if (
      u.shape === "oval" &&
      u.orientation === "parallel" &&
      u.margin === "circumscribed"
    ) {
      probablyBenign = true;
    }
  }
}

if (probablyBenign) {

  result.assessment_category = "3";
  result.assessment_label = "Probably Benign";

  result.management_recommendation =
    "Short-interval imaging follow-up is generally recommended for an appropriate BI-RADS 3 assessment.";

  addBasis(
    "The structured findings contain features that may support a probably benign assessment."
  );

  addWarning(
    "Category 3 requires radiologist assessment of the complete imaging appearance and clinical context; this tool does not independently establish malignancy probability."
  );

  result.status = "complete";

  return JSON.stringify(result);
}

// ==========================================
// HIGHLY SUSPICIOUS FINDINGS
// BI-RADS 5
// ==========================================

let highlySuspicious = false;

// ------------------------------------------
// Mammography
// ------------------------------------------

if (input.modality === "mammography") {

  for (const finding of input.findings) {

    const m = finding.mammography || {};

    // New or increasing spiculated mass
    if (
      m.mass_margin === "spiculated" &&
      (
        finding.change_from_prior === "new" ||
        finding.change_from_prior === "increased"
      )
    ) {

      highlySuspicious = true;

      addBasis(
        "A new or increasing spiculated mammographic mass was identified."
      );
    }

    // Fine linear / fine-linear branching calcifications
    // with linear or segmental distribution
    if (
      m.calcification_morphology ===
        "fine_linear_or_fine_linear_branching" &&
      (
        m.calcification_distribution === "linear" ||
        m.calcification_distribution === "segmental"
      )
    ) {

      highlySuspicious = true;

      addBasis(
        "Fine linear or fine-linear branching calcifications with a linear or segmental distribution were identified."
      );
    }
  }
}

// ------------------------------------------
// Ultrasound
// ------------------------------------------

if (input.modality === "ultrasound") {

  for (const finding of input.findings) {

    const u = finding.ultrasound || {};

    // Extremely suspicious combination
    if (
      u.shape === "irregular" &&
      u.orientation === "not_parallel" &&
      (
        u.margin === "spiculated" ||
        u.margin === "angular"
      )
    ) {

      highlySuspicious = true;

      addBasis(
        "A highly suspicious ultrasound mass pattern was identified."
      );
    }
  }
}

// ------------------------------------------
// MRI
// ------------------------------------------

if (input.modality === "mri") {

  for (const finding of input.findings) {

    const r = finding.mri || {};

    if (
      r.mass_margin === "spiculated" &&
      r.mass_shape === "irregular"
    ) {

      highlySuspicious = true;

      addBasis(
        "An irregular spiculated MRI mass was identified."
      );
    }

    if (
      r.mass_internal_enhancement === "rim"
    ) {

      highlySuspicious = true;

      addBasis(
        "Rim enhancement was identified in the MRI mass."
      );
    }

    if (
      r.non_mass_distribution === "segmental" &&
      r.non_mass_internal_enhancement === "clustered_ring"
    ) {

      highlySuspicious = true;

      addBasis(
        "Segmental clustered-ring non-mass enhancement was identified."
      );
    }
  }
}

// ==========================================
// BI-RADS 5
// ==========================================

if (highlySuspicious) {

  result.assessment_category = "5";

  result.assessment_label =
    "Highly Suggestive of Malignancy";

  result.management_recommendation =
    "Appropriate action should be taken; tissue diagnosis is generally required.";

  addWarning(
    "Category 5 indicates a highly suspicious imaging appearance; final assessment requires complete radiologist interpretation."
  );

  result.status = "complete";

  return JSON.stringify(result);
}

// ==========================================
// SUSPICIOUS FINDINGS
// BI-RADS 4
// ==========================================

let suspicious = false;

// ------------------------------------------
// Mammography suspicious features
// ------------------------------------------

if (input.modality === "mammography") {

  for (const finding of input.findings) {

    const m = finding.mammography || {};

    if (
      m.mass_margin === "spiculated" ||
      m.asymmetry_type === "developing_asymmetry" ||
      m.architectural_distortion === true ||
      m.calcification_morphology === "fine_pleomorphic" ||
      m.calcification_morphology ===
        "fine_linear_or_fine_linear_branching"
    ) {

      suspicious = true;
    }
  }
}

// ------------------------------------------
// Ultrasound suspicious features
// ------------------------------------------

if (input.modality === "ultrasound") {

  for (const finding of input.findings) {

    const u = finding.ultrasound || {};

    if (
      u.orientation === "not_parallel" ||
      u.margin === "spiculated" ||
      u.margin === "angular" ||
      u.margin === "indistinct"
    ) {

      suspicious = true;
    }
  }
}

// ------------------------------------------
// MRI suspicious features
// ------------------------------------------

if (input.modality === "mri") {

  for (const finding of input.findings) {

    const r = finding.mri || {};

    if (
      r.mass_margin === "spiculated" ||
      r.mass_shape === "irregular" ||
      r.mass_internal_enhancement === "rim" ||
      r.non_mass_distribution === "segmental" ||
      r.non_mass_internal_enhancement === "clustered_ring" ||
      r.kinetic_pattern === "washout"
    ) {

      suspicious = true;
    }
  }
}

// ==========================================
// BI-RADS 4
// ==========================================

if (suspicious) {

  result.assessment_category = "4";
  result.assessment_label = "Suspicious";

  result.management_recommendation =
    "Biopsy should be considered based on the complete imaging assessment.";

  addBasis(
    "Suspicious imaging descriptors were identified."
  );

  addWarning(
    "Category 4 subcategories (4A, 4B, 4C) are not assigned by this tool."
  );

  result.status = "complete";

  return JSON.stringify(result);
}

// ==========================================
// Insufficient data
// ==========================================

result.assessment_category = null;
result.assessment_label = null;
result.management_recommendation = null;

addWarning(
  "The available structured findings are insufficient to assign a BI-RADS assessment category."
);

result.status = "insufficient_data";

// ==========================================
// Final output for n8n Tool Code
// ==========================================

return JSON.stringify(result);

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "modality": {
      "type": "string",
      "enum": [
        "mammography",
        "ultrasound",
        "mri"
      ],
      "description": "Breast imaging modality used for the examination."
    },

    "clinical_context": {
      "type": "string",
      "enum": [
        "screening",
        "diagnostic",
        "symptomatic",
        "follow_up",
        "post_treatment",
        "known_malignancy",
        "unknown"
      ],
      "description": "Clinical context of the breast imaging examination."
    },

    "comparison_available": {
      "type": "boolean",
      "description": "Whether relevant prior breast imaging is available for comparison."
    },

    "additional_imaging_needed": {
      "type": "boolean",
      "description": "Whether the current evaluation is incomplete and additional imaging or prior comparison is required before a final assessment can be assigned."
    },

    "known_biopsy_proven_malignancy": {
      "type": "boolean",
      "description": "Whether there is a known biopsy-proven breast malignancy corresponding to the imaging finding."
    },

    "findings": {
      "type": "array",
      "description": "Structured imaging findings extracted from the radiologist's description. Findings must describe observed imaging features and must not contain a pre-assigned BI-RADS category.",
      "items": {
        "type": "object",
        "properties": {

          "finding_type": {
            "type": "string",
            "enum": [
              "mass",
              "calcifications",
              "asymmetry",
              "architectural_distortion",
              "non_mass_finding",
              "cyst",
              "no_suspicious_finding",
              "other"
            ],
            "description": "Primary type of breast imaging finding."
          },

          "location": {
            "type": "string",
            "description": "Anatomic location including laterality, quadrant, clock-face position, depth, or other location information when provided."
          },

          "size_mm": {
            "type": "number",
            "minimum": 0,
