parameters.jsCode:
// Prostate Volume + PSA Density Code Tool
// Calculates prostate volume and PSA density

const input = $json;

// -----------------------------
// Required fields
// -----------------------------

const requiredFields = [
  "prostate_length_mm",
  "prostate_width_mm",
  "prostate_height_mm",
  "psa_ng_ml"
];

// -----------------------------
// Check missing fields
// -----------------------------

const missingFields = requiredFields.filter(
  field =>
    input[field] === undefined ||
    input[field] === null
);

if (missingFields.length > 0) {
  return JSON.stringify({
    status: "missing_information",
    calculator: "Prostate Volume + PSA Density",

    findings: {
      prostate_length_mm: input.prostate_length_mm ?? null,
      prostate_width_mm: input.prostate_width_mm ?? null,
      prostate_height_mm: input.prostate_height_mm ?? null,
      psa_ng_ml: input.psa_ng_ml ?? null
    },

    result: null,

    missing_fields: missingFields,

    message:
      `Missing required value(s): ${missingFields.join(", ")}`
  });
}

// -----------------------------
// Validate numeric values
// -----------------------------

const numericFields = [
  "prostate_length_mm",
  "prostate_width_mm",
  "prostate_height_mm",
  "psa_ng_ml"
];

const invalidFields = numericFields.filter(
  field =>
    typeof input[field] !== "number" ||
    !Number.isFinite(input[field])
);

if (invalidFields.length > 0) {
  return JSON.stringify({
    status: "invalid_input",
    calculator: "Prostate Volume + PSA Density",

    findings: {
      prostate_length_mm: input.prostate_length_mm ?? null,
      prostate_width_mm: input.prostate_width_mm ?? null,
      prostate_height_mm: input.prostate_height_mm ?? null,
      psa_ng_ml: input.psa_ng_ml ?? null
    },

    result: null,

    invalid_fields: invalidFields,

    message:
      `Invalid numeric value(s): ${invalidFields.join(", ")}`
  });
}

// -----------------------------
// Validate positive values
// -----------------------------

const nonPositiveFields = numericFields.filter(
  field => input[field] <= 0
);

if (nonPositiveFields.length > 0) {
  return JSON.stringify({
    status: "invalid_input",
    calculator: "Prostate Volume + PSA Density",

    findings: {
      prostate_length_mm: input.prostate_length_mm,
      prostate_width_mm: input.prostate_width_mm,
      prostate_height_mm: input.prostate_height_mm,
      psa_ng_ml: input.psa_ng_ml
    },

    result: null,

    invalid_fields: nonPositiveFields,

    message:
      `Value(s) must be greater than 0: ${nonPositiveFields.join(", ")}`
  });
}

// -----------------------------
// Calculate prostate volume
// -----------------------------

const length_cm =
  input.prostate_length_mm / 10;

const width_cm =
  input.prostate_width_mm / 10;

const height_cm =
  input.prostate_height_mm / 10;

// Ellipsoid formula
const prostateVolume =
  length_cm *
  width_cm *
  height_cm *
  0.52;

// -----------------------------
// Calculate PSA density
// -----------------------------

const psaDensity =
  input.psa_ng_ml / prostateVolume;

// -----------------------------
// Round results
// -----------------------------

const roundedVolume =
  Number(prostateVolume.toFixed(2));

const roundedPSADensity =
  Number(psaDensity.toFixed(3));

// -----------------------------
// Final response
// -----------------------------

return JSON.stringify({
  status: "calculated",
  calculator: "Prostate Volume + PSA Density",

  findings: {
    prostate_length_mm: input.prostate_length_mm,
    prostate_width_mm: input.prostate_width_mm,
    prostate_height_mm: input.prostate_height_mm,
    psa_ng_ml: input.psa_ng_ml
  },

  result: {
    prostate_volume_ml: roundedVolume,
    psa_density_ng_ml_per_ml: roundedPSADensity
  }
});

