parameters.jsCode:
const input = query;

if (!input || typeof input !== "object") {
  return JSON.stringify({
    status: "error",
    calculator: "PI-RADS",
    zone: "TZ",
    message: "Invalid calculator input."
  });
}

const zone = String(input.zone || "TZ").trim().toUpperCase();

if (zone !== "TZ") {
  return JSON.stringify({
    status: "unsupported_or_missing",
    calculator: "PI-RADS",
    message: "This tool calculates transition zone (TZ) lesions only.",
    received_zone: input.zone
  });
}

// =====================================================
// READ FLAT INPUTS
// =====================================================

const size = input.lesion_size_mm;

const t2 = {
  signal_intensity: input.t2_signal_intensity || "",
  homogeneity: input.t2_homogeneity || "",
  shape: input.t2_shape || "",
  margin: input.t2_margin || "",
  encapsulation: input.t2_encapsulation || "",
  nodule_type: input.t2_nodule_type || "",
  epe_or_invasion: input.t2_epe_or_invasion === true
};

const dwi = {
  adc: input.dwi_adc || "",
  high_b_value_dwi: input.dwi_high_b_value || "",
  restriction: input.dwi_restriction || "",
  focal: input.dwi_focal === true
};


// =====================================================
// NORMALIZE T2 FINDINGS
// =====================================================

const signal = String(t2.signal_intensity).toLowerCase();
const homogeneity = String(t2.homogeneity).toLowerCase();
const shape = String(t2.shape).toLowerCase();
const margin = String(t2.margin).toLowerCase();
const encapsulation = String(t2.encapsulation).toLowerCase();
const noduleType = String(t2.nodule_type).toLowerCase();

const epe = t2.epe_or_invasion === true;


// =====================================================
// NORMALIZE DWI FINDINGS
// =====================================================

const adc = String(dwi.adc).toLowerCase();
const highB = String(dwi.high_b_value_dwi).toLowerCase();
const restriction = String(dwi.restriction).toLowerCase();

const focal =
  dwi.focal === true ||
  restriction.includes("focal");


// =====================================================
// DETERMINE T2 FEATURES
// =====================================================

const homogeneous =
  homogeneity.includes("homogeneous") &&
  !homogeneity.includes("heterogeneous");

const heterogeneous =
  homogeneity.includes("heterogeneous") ||
  signal.includes("heterogeneous");

const round =
  shape.includes("round");

const lenticular =
  shape.includes("lenticular");

const nonCircumscribed =
  margin.includes("non-circumscribed") ||
  margin.includes("noncircumscribed") ||
  margin.includes("poorly defined");

const poorlyDefined =
  margin.includes("poorly defined") ||
  margin.includes("obscured");

const completelyEncapsulated =
  encapsulation.includes("completely") ||
  encapsulation.includes("complete") ||
  margin.includes("completely encapsulated");

const partiallyEncapsulated =
  encapsulation.includes("partially") ||
  encapsulation.includes("partial") ||
  margin.includes("partially encapsulated");

const mostlyEncapsulated =
  encapsulation.includes("mostly");

const nonEncapsulated =
  encapsulation.includes("non") ||
  margin.includes("non-encapsulated") ||
  margin.includes("nonencapsulated");

const moderatelyHypointense =
  signal.includes("moderately hypointense") ||
  signal.includes("moderate hypointense") ||
  (
    signal.includes("moderate") &&
    signal.includes("hypointense")
  );

const mildlyHypointense =
  signal.includes("mildly hypointense") ||
  signal.includes("mild hypointense") ||
  (
    signal.includes("mild") &&
    signal.includes("hypointense")
  );


// =====================================================
// DETERMINE T2 SCORE
// =====================================================

let t2Score = null;
let t2Rule = "";


// =====================================================
// T2 SCORE 5
// =====================================================

if (epe) {

  t2Score = 5;

  t2Rule =
    "T2 score 5 because definite EPE or invasive behavior is present.";

} else if (
  lenticular &&
  nonCircumscribed &&
  homogeneous &&
  moderatelyHypointense &&
  typeof size === "number" &&
  size > 15
) {

  t2Score = 5;

  t2Rule =
    "T2 score 5 because the lesion is lenticular, non-circumscribed, homogeneous, moderately hypointense, and greater than 15 mm.";
}


// =====================================================
// T2 SCORE 4
// =====================================================

else if (
  lenticular &&
  nonCircumscribed &&
  homogeneous &&
  moderatelyHypointense &&
  typeof size === "number" &&
  size < 15
) {

  t2Score = 4;

  t2Rule =
    "T2 score 4 because the lesion is lenticular, non-circumscribed, homogeneous, moderately hypointense, and less than 15 mm.";
}


// =====================================================
// EXACTLY 15 MM = BOUNDARY CASE
// =====================================================

else if (
  lenticular &&
  nonCircumscribed &&
  homogeneous &&
  moderatelyHypointense &&
  typeof size === "number" &&
  size === 15
) {

  return JSON.stringify({
    status: "boundary_case",
    calculator: "PI-RADS",
    zone: "TZ",
    message:
      "Lesion size is exactly 15 mm. This is a boundary case in the reference for TZ T2 scoring.",
    t2_findings: t2,
    lesion_size_mm: size
  });
}


// =====================================================
// T2 SCORE 3
// =====================================================

else if (
  heterogeneous ||
  poorlyDefined ||
  noduleType.includes("heterogeneous")
) {

  t2Score = 3;

  t2Rule =
    "T2 score 3 because the lesion is heterogeneous or poorly defined and does not meet T2 score 2, 4, or 5.";
}


// =====================================================
// T2 SCORE 1
// =====================================================

else if (
  noduleType.includes("normal") ||
  (
    noduleType.includes("typical") &&
    !noduleType.includes("atypical")
  ) ||
  (
    homogeneous &&
    round &&
    completelyEncapsulated
  )
) {

  t2Score = 1;

  t2Rule =
    "T2 score 1 because the TZ is normal appearing or the lesion is a homogeneous, round, completely encapsulated typical nodule.";
}


// =====================================================
// T2 SCORE 2
// =====================================================

else if (
  mostlyEncapsulated ||
  (
    homogeneous &&
    round &&
    (
      partiallyEncapsulated ||
      nonEncapsulated
    )
  ) ||
  (
    homogeneous &&
    mildlyHypointense &&
    (
      noduleType.includes("between nodules") ||
      noduleType.includes("between")
    )
  ) ||
  noduleType.includes("atypical")
) {

  t2Score = 2;

  t2Rule =
    "T2 score 2 because the lesion matches an atypical TZ nodule pattern.";
}


// =====================================================
// NO DETERMINISTIC T2 SCORE
// =====================================================

else {

  return JSON.stringify({
    status: "insufficient_information",
    calculator: "PI-RADS",
    zone: "TZ",
    message:
      "The provided T2-weighted findings do not allow a deterministic TZ T2 score to be assigned.",
    missing_information: [
      "Additional T2 lesion characteristics are required."
    ],
    received_findings: {
      t2: t2,
      lesion_size_mm: size
    }
  });
}


// =====================================================
// DETERMINE DWI SCORE
// Same DWI criteria are used for PZ and TZ
// =====================================================

const markedADC =
  adc.includes("marked") &&
  (
    adc.includes("low") ||
    adc.includes("hypointense")
  );

const markedHighB =
  highB.includes("marked") ||
  highB.includes("high signal") ||
  highB.includes("hyperintense") ||
  highB.includes("high intensity");

const markedRestriction =
  restriction.includes("marked") ||
  (markedADC && markedHighB);

const noRestriction =
  restriction.includes("no restriction") ||
  restriction.includes("no diffusion restriction") ||
  restriction.includes("no restricted") ||
  restriction.includes("normal") ||
  restriction.includes("none");

const mildRestriction =
  restriction.includes("mild") ||
  restriction.includes("slight");

let dwiScore = null;


// =====================================================
// DWI SCORE 5
// =====================================================

if (epe) {

  dwiScore = 5;

} else if (
  markedRestriction &&
  focal &&
  typeof size === "number" &&
  size > 15
) {

  dwiScore = 5;


// =====================================================
// EXACTLY 15 MM = BOUNDARY CASE
// =====================================================

} else if (
  markedRestriction &&
  focal &&
  typeof size === "number" &&
  size === 15
) {

  return JSON.stringify({
    status: "boundary_case",
    calculator: "PI-RADS",
    zone: "TZ",
    component_scores: {
      t2: t2Score
    },
    message:
      "Lesion size is exactly 15 mm. This is a boundary case for DWI size-based scoring.",
    t2_rule: t2Rule,
    dwi_findings: dwi
  });


// =====================================================
// DWI SCORE 4
// =====================================================

} else if (
  markedRestriction &&
  focal &&
  typeof size === "number" &&
  size < 15
) {

  dwiScore = 4;


// =====================================================
// DWI SCORE 3
// =====================================================

} else if (
  focal ||
  restriction.includes("focal")
) {

  dwiScore = 3;


// =====================================================
// DWI SCORE 1
// =====================================================

} else if (
  noRestriction
) {

  dwiScore = 1;


// =====================================================
// DWI SCORE 2
// =====================================================

} else if (
  mildRestriction ||
  (
    !markedRestriction &&
    !noRestriction &&
    (
      adc ||
      highB ||
      restriction
    )
  )
) {

  dwiScore = 2;

} else {

  return JSON.stringify({
    status: "insufficient_information",
    calculator: "PI-RADS",
    zone: "TZ",
    component_scores: {
      t2: t2Score
    },
    message:
      "The provided DWI findings do not allow a deterministic DWI score to be assigned.",
    missing_information: [
      "DWI findings sufficient to determine a score from 1 to 5."
    ],
    t2_rule: t2Rule,
    received_findings: {
      t2: t2,
      dwi: dwi,
      lesion_size_mm: size
    }
  });
}


// =====================================================
// COMBINE T2 + DWI
// PI-RADS v2.1 TZ TABLE 6
// =====================================================

let finalCategory = null;
let combinedRule = "";

if (t2Score === 1) {

  finalCategory = 1;

  combinedRule =
    "T2 1 gives overall PI-RADS 1 regardless of DWI.";

} else if (t2Score === 2) {

  if (dwiScore <= 3) {

    finalCategory = 2;

    combinedRule =
      "T2 2 plus DWI <= 3 gives overall PI-RADS 2.";

  } else {

    finalCategory = 3;

    combinedRule =
      "T2 2 plus DWI >= 4 gives overall PI-RADS 3.";
  }

} else if (t2Score === 3) {

  if (dwiScore <= 4) {

    finalCategory = 4;

    combinedRule =
      "T2 3 plus DWI <= 4 gives overall PI-RADS 4.";

  } else {

    finalCategory = 4;

    combinedRule =
      "T2 3 plus DWI 5 gives overall PI-RADS 4.";
  }

} else if (t2Score === 4) {

  finalCategory = 4;

  combinedRule =
    "T2 4 gives overall PI-RADS 4 regardless of DWI.";

} else if (t2Score === 5) {

  finalCategory = 5;

  combinedRule =
    "T2 5 gives overall PI-RADS 5 regardless of DWI.";
}


// =====================================================
// FINAL RESULT
// =====================================================

return JSON.stringify({
  status: "calculated",
  calculator: "PI-RADS",
  zone: "TZ",

  component_scores: {
    t2: t2Score,
    dwi: dwiScore
  },

  final_category: finalCategory,

  rule_applied: combinedRule,

  t2_rule: t2Rule,

  received_findings: {
    lesion_size_mm: size,
    t2: t2,
    dwi: dwi
  },

  reference: {
    guideline: "PI-RADS v2.1",
    source: "SAJR-25-2062.pdf",
    tables: [
      "Table 5 - TZ lesion T2 scoring",
      "Table 6 - Combined TZ scoring"
    ]
  }
});

