parameters.jsCode:
const input = query;

if (!input || typeof input !== "object") {
  return JSON.stringify({
    status: "error",
    calculator: "PI-RADS",
    zone: "PZ",
    message: "Invalid calculator input."
  });
}


// =====================================================
// VALIDATE ZONE
// =====================================================

const zone = String(input.zone || "PZ").trim().toUpperCase();

if (zone !== "PZ") {
  return JSON.stringify({
    status: "unsupported_or_missing",
    calculator: "PI-RADS",
    zone: zone,
    message: "This tool calculates peripheral zone (PZ) lesions only."
  });
}


// =====================================================
// READ FLAT INPUTS
// =====================================================

const size = input.lesion_size_mm;

const adc =
  String(input.dwi_adc || "")
    .trim()
    .toLowerCase();

const highB =
  String(input.dwi_high_b_value || "")
    .trim()
    .toLowerCase();

const restriction =
  String(input.dwi_restriction || "")
    .trim()
    .toLowerCase();

const focal = input.dwi_focal === true;

const epe = input.dwi_epe_or_invasion === true;

const dceText =
  String(input.dce_enhancement || "")
    .trim()
    .toLowerCase();


// =====================================================
// DWI FEATURE DETECTION
// =====================================================


// Normal / no restriction

const noRestriction =
  restriction.includes("no restriction") ||
  restriction.includes("no restricted") ||
  restriction.includes("no diffusion restriction") ||
  restriction === "none" ||
  restriction === "normal" ||
  (
    adc.includes("normal") &&
    (
      highB.includes("normal") ||
      highB.includes("no abnormal") ||
      highB.includes("no high")
    )
  );


// Linear or wedge-shaped morphology

const linearOrWedge =
  restriction.includes("linear") ||
  restriction.includes("wedge");


// Markedly low ADC

const markedADC =
  adc.includes("marked") &&
  (
    adc.includes("low") ||
    adc.includes("hypointense")
  );


// Markedly high signal on high b-value DWI
// IMPORTANT: "high signal" alone is NOT considered marked.
// "marked" must be explicitly present.

const markedHighB =
  highB.includes("marked") &&
  (
    highB.includes("high") ||
    highB.includes("hyperintense") ||
    highB.includes("high signal") ||
    highB.includes("high intensity")
  );


// Any marked DWI abnormality

const anyMarked =
  markedADC || markedHighB;


// Focal diffusion abnormality

const focalRestriction =
  focal ||
  restriction.includes("focal");


// Mild restriction

const mildRestriction =
  restriction.includes("mild") ||
  restriction.includes("slight");


// =====================================================
// DCE
// =====================================================

// DCE is missing when the model sends not_provided,
// not provided, or an empty string.

const dceMissing =
  dceText === "not_provided" ||
  dceText === "not provided" ||
  dceText === "";


// DCE positive

const dcePositive =
  !dceMissing &&
  (
    dceText.includes("positive") ||
    dceText.includes("early enhancement") ||
    dceText.includes("focal enhancement") ||
    dceText.includes("focal early enhancement") ||
    dceText.includes("positive enhancement")
  );


// DCE negative

const dceNegative =
  !dceMissing &&
  (
    dceText.includes("negative") ||
    dceText.includes("no enhancement") ||
    dceText.includes("not positive") ||
    dceText.includes("no focal enhancement")
  );


// =====================================================
// CHECK BASIC DWI INFORMATION
// =====================================================

if (
  !restriction ||
  restriction === "not_provided" ||
  !adc ||
  adc === "not_provided" ||
  !highB ||
  highB === "not_provided"
) {
  return JSON.stringify({
    status: "missing_information",
    calculator: "PI-RADS",
    zone: "PZ",
    missing_information: [
      "DWI restriction",
      "ADC finding",
      "High b-value DWI finding"
    ],
    message:
      "DWI information is required to calculate the PZ PI-RADS category."
  });
}


// =====================================================
// DWI SCORE 5 — EPE / INVASION
// =====================================================

if (epe) {

  return JSON.stringify({
    status: "calculated",
    calculator: "PI-RADS",
    zone: "PZ",

    component_scores: {
      dwi: 5
    },

    final_category: 5,

    rule_applied:
      "DWI 5 because definite extra-prostatic extension or invasive behavior is present.",

    received_findings: {
      lesion_size_mm: size,
      adc: input.dwi_adc || "",
      high_b_value_dwi: input.dwi_high_b_value || "",
      restriction: input.dwi_restriction || "",
      focal: focal,
      epe_or_invasion: epe,
      dce: input.dce_enhancement || ""
    }
  });
}


// =====================================================
// DWI SCORE 1
// =====================================================

if (noRestriction) {

  return JSON.stringify({
    status: "calculated",
    calculator: "PI-RADS",
    zone: "PZ",

    component_scores: {
      dwi: 1
    },

    final_category: 1,

    rule_applied:
      "DWI 1 gives overall PI-RADS 1 in the peripheral zone.",

    received_findings: {
      lesion_size_mm: size,
      adc: input.dwi_adc || "",
      high_b_value_dwi: input.dwi_high_b_value || "",
      restriction: input.dwi_restriction || "",
      focal: focal,
      epe_or_invasion: epe,
      dce: input.dce_enhancement || ""
    }
  });
}


// =====================================================
// DWI SCORE 2
// Linear or wedge-shaped morphology
// =====================================================

if (linearOrWedge) {

  return JSON.stringify({
    status: "calculated",
    calculator: "PI-RADS",
    zone: "PZ",

    component_scores: {
      dwi: 2
    },

    final_category: 2,

    rule_applied:
      "Linear or wedge-shaped diffusion abnormality gives DWI 2 and overall PI-RADS 2.",

    received_findings: {
      lesion_size_mm: size,
      adc: input.dwi_adc || "",
      high_b_value_dwi: input.dwi_high_b_value || "",
      restriction: input.dwi_restriction || "",
      focal: focal,
      epe_or_invasion: epe,
      dce: input.dce_enhancement || ""
    }
  });
}


// =====================================================
// DWI SCORE 5
// Marked focal restriction > 15 mm
// =====================================================

if (
  markedADC &&
  markedHighB &&
  focalRestriction &&
  typeof size === "number" &&
  size > 15
) {

  return JSON.stringify({
    status: "calculated",
    calculator: "PI-RADS",
    zone: "PZ",

    component_scores: {
      dwi: 5
    },

    final_category: 5,

    rule_applied:
      "DWI 5 because there is marked focal diffusion restriction and the lesion is greater than 15 mm.",

    received_findings: {
      lesion_size_mm: size,
      adc: input.dwi_adc || "",
      high_b_value_dwi: input.dwi_high_b_value || "",
      restriction: input.dwi_restriction || "",
      focal: focal,
      epe_or_invasion: epe,
      dce: input.dce_enhancement || ""
    }
  });
}


// =====================================================
// EXACTLY 15 MM — BOUNDARY CASE
// =====================================================

if (
  markedADC &&
  markedHighB &&
  focalRestriction &&
  typeof size === "number" &&
  size === 15
) {

  return JSON.stringify({
    status: "boundary_case",
    calculator: "PI-RADS",
    zone: "PZ",

    message:
      "Lesion size is exactly 15 mm. This is a boundary case for size-based DWI scoring.",

    lesion_size_mm: size,

    dwi_findings: {
      adc: input.dwi_adc || "",
      high_b_value_dwi: input.dwi_high_b_value || "",
      restriction: input.dwi_restriction || "",
      focal: focal
    }
  });
}


// =====================================================
// DWI SCORE 4
// Marked focal restriction < 15 mm
// =====================================================

if (
  markedADC &&
  markedHighB &&
  focalRestriction &&
  typeof size === "number" &&
  size < 15
) {

  return JSON.stringify({
    status: "calculated",
    calculator: "PI-RADS",
    zone: "PZ",

    component_scores: {
      dwi: 4
    },

    final_category: 4,

    rule_applied:
      "DWI 4 because there is marked focal diffusion restriction and the lesion is less than 15 mm.",

    received_findings: {
      lesion_size_mm: size,
      adc: input.dwi_adc || "",
      high_b_value_dwi: input.dwi_high_b_value || "",
      restriction: input.dwi_restriction || "",
      focal: focal,
      epe_or_invasion: epe,
      dce: input.dce_enhancement || ""
    }
  });
}


// =====================================================
// DWI SCORE 3
// Focal abnormality without both marked ADC and marked high-b DWI
// =====================================================

if (focalRestriction) {

  const dwi3 =
    (!markedADC && !markedHighB) ||
    (anyMarked && !(markedADC && markedHighB));

  if (dwi3) {

    // -----------------------------------------------
    // DWI 3 + DCE MISSING
    // -----------------------------------------------

    if (dceMissing) {

      return JSON.stringify({
        status: "needs_dce",
        calculator: "PI-RADS",
        zone: "PZ",

        component_scores: {
          dwi: 3
        },

        missing_information: [
          "DCE finding: positive or negative"
        ],

        message:
          "DWI score is 3. DCE is required to determine the final PI-RADS category.",

        received_findings: {
          lesion_size_mm: size,
          adc: input.dwi_adc || "",
          high_b_value_dwi: input.dwi_high_b_value || "",
          restriction: input.dwi_restriction || "",
          focal: focal,
          epe_or_invasion: epe,
          dce: input.dce_enhancement || ""
        }
      });
    }


    // -----------------------------------------------
    // DWI 3 + POSITIVE DCE = PI-RADS 4
    // -----------------------------------------------

    if (dcePositive && !dceNegative) {

      return JSON.stringify({
        status: "calculated",
        calculator: "PI-RADS",
        zone: "PZ",

        component_scores: {
          dwi: 3,
          dce: "positive"
        },

        final_category: 4,

        rule_applied:
          "DWI 3 plus positive DCE gives overall PI-RADS 4.",

        received_findings: {
          lesion_size_mm: size,
          adc: input.dwi_adc || "",
          high_b_value_dwi: input.dwi_high_b_value || "",
          restriction: input.dwi_restriction || "",
          focal: focal,
          epe_or_invasion: epe,
          dce: input.dce_enhancement || ""
        }
      });
    }


    // -----------------------------------------------
    // DWI 3 + NEGATIVE DCE = PI-RADS 3
    // -----------------------------------------------

    if (dceNegative && !dcePositive) {

      return JSON.stringify({
        status: "calculated",
        calculator: "PI-RADS",
        zone: "PZ",

        component_scores: {
          dwi: 3,
          dce: "negative"
        },

        final_category: 3,

        rule_applied:
          "DWI 3 plus negative DCE gives overall PI-RADS 3.",

        received_findings: {
          lesion_size_mm: size,
          adc: input.dwi_adc || "",
          high_b_value_dwi: input.dwi_high_b_value || "",
          restriction: input.dwi_restriction || "",
          focal: focal,
          epe_or_invasion: epe,
          dce: input.dce_enhancement || ""
        }
      });
    }


    // -----------------------------------------------
    // DWI 3 + UNKNOWN DCE VALUE
    // -----------------------------------------------

    return JSON.stringify({
      status: "needs_dce",
      calculator: "PI-RADS",
      zone: "PZ",

      component_scores: {
        dwi: 3
      },

      missing_information: [
        "DCE finding: positive or negative"
      ],

      message:
        "DWI score is 3. DCE must be explicitly provided as positive or negative.",

      received_findings: {
        lesion_size_mm: size,
        adc: input.dwi_adc || "",
        high_b_value_dwi: input.dwi_high_b_value || "",
        restriction: input.dwi_restriction || "",
        focal: focal,
        epe_or_invasion: epe,
        dce: input.dce_enhancement || ""
      }
    });
  }
}


// =====================================================
// DWI SCORE 2 — OTHER NON-SPECIFIC LOW-GRADE FINDINGS
// =====================================================

if (mildRestriction) {

  return JSON.stringify({
    status: "calculated",
    calculator: "PI-RADS",
    zone: "PZ",

    component_scores: {
      dwi: 2
    },

    final_category: 2,

    rule_applied:
      "Mild diffusion restriction gives DWI 2 and overall PI-RADS 2.",

    received_findings: {
      lesion_size_mm: size,
      adc: input.dwi_adc || "",
      high_b_value_dwi: input.dwi_high_b_value || "",
      restriction: input.dwi_restriction || "",
      focal: focal,
      epe_or_invasion: epe,
      dce: input.dce_enhancement || ""
    }
  });
}


// =====================================================
// INSUFFICIENT INFORMATION
// =====================================================

return JSON.stringify({
  status: "insufficient_information",
  calculator: "PI-RADS",
  zone: "PZ",

  message:
    "The provided DWI findings do not allow a deterministic PZ PI-RADS score to be assigned.",

  missing_information: [
    "Additional DWI characteristics are required."
  ],

  received_findings: {
    lesion_size_mm: size,
    adc: input.dwi_adc || "",
    high_b_value_dwi: input.dwi_high_b_value || "",
    restriction: input.dwi_restriction || "",
    focal: focal,
    epe_or_invasion: epe,
    dce: input.dce_enhancement || ""
  },

  reference: {
    guideline: "PI-RADS v2.1"
  }
});

