parameters.jsCode:
/**
 * RADRAFT — RE-IDENTIFICATION
 *
 * Restores protected identifiers in the AI Agent's
 * output using the original trusted PHI mapping.
 *
 * Input:
 *   AI Agent - Calculator → output
 *
 * Trusted mapping:
 *   Data from Workflow 2 → mapping
 *
 * Output:
 *   output
 *   current_report
 *   chat_id
 *   reidentification_status
 *
 * Mode: Run Once for All Items
 */

const aiItems = $input.all();

const source = $('Data from Workflow 2').first().json;

// Trusted mapping from Workflow 2.
const mapping = source.mapping ?? {};

if (
  typeof mapping !== 'object' ||
  mapping === null ||
  Array.isArray(mapping)
) {
  throw new Error(
    'REIDENTIFICATION_ERROR: Invalid PHI mapping.'
  );
}

const output = [];

for (const item of aiItems) {

  const rawReport = item.json.output;

  if (typeof rawReport !== 'string') {
    throw new Error(
      'REIDENTIFICATION_ERROR: AI Agent output is missing.'
    );
  }

  let report = rawReport;

  let replacements = 0;

  // Replace only exact authorized placeholders.
  report = report.replace(
    /\[([A-Z][A-Z0-9_]*_\d+)\]/g,
    (placeholder) => {

      if (
        Object.prototype.hasOwnProperty.call(
          mapping,
          placeholder
        )
      ) {

        const original = mapping[placeholder];

        if (typeof original !== 'string') {
          throw new Error(
            'REIDENTIFICATION_ERROR: Invalid mapping value.'
          );
        }

        replacements++;

        return original;
      }

      // Preserve unknown placeholders.
      return placeholder;
    }
  );

  output.push({
    json: {
      ...item.json,

      output: report,
      current_report: report,

      chat_id: String(
        source.chat_id ??
        item.json.chat_id ??
        ''
      ),

      reidentification_status:
        replacements > 0
          ? 'COMPLETED'
          : 'NO_MATCHING_PLACEHOLDERS',

      restored_identifiers: replacements
    }
  });
}

return output;
